function productionSummary() {
 const cfg=configAt(state.date);
 return `<aside class="summary"><h3>Produção do dia</h3><dl>${names.map((name,i)=>`<div><dt>${esc(name)}</dt><dd>${measured(i)?liters(generalTotal(i)):'Não aferida'}</dd></div>`).join('')}<div class="total"><dt>Total registrado</dt><dd>${byDay().length?liters(byDay().reduce((sum,r)=>sum+r.liters,0)):'Não informado'}</dd></div></dl><p class="context-note">Somente aferições salvas. Ausência de aferição não significa zero.</p>
 ${MockupUI.ActionPanel({title:'Controle individual',description:`A cada ${cfg.intervalo} ${cfg.unidade==='MESES'?'mês(es)':'dia(s)'}.`,body:'<p>O controle por animal continua disponível. Seus litros não se somam à fonte geral.</p>',actions:MockupUI.Button('Ver ficha de Aurora','data-go="animal"',icon('cow'))})}
 ${MockupUI.ActionPanel({title:'Tanques cadastrados',description:`${activeTanks().length} disponíveis nesta data. Escolha o utilizado em cada ordenha.`,actions:MockupUI.Button('Gerenciar tanques','id="manage-tanks"',icon('settings'))})}</aside>`;
}
function originsPanel(t,d,r) {
 return MockupUI.ActionPanel({
   title:`Animais de origem · ${d.origins.length}`,
   description:r?'Seleção preservada desta aferição.':'Pré-seleção: finalidade Leite e DEL > 0 na data da ordenha.',
   body:'<p>Identifica a população de origem sem atribuir litros por animal.</p>',
   actions:MockupUI.Button(r?.confirmed?'Ver animais':'Conferir animais',`data-review-origins="${t.id}"`,icon('cow')),
   className:'origin-panel'
 });
}
function originsDialog(id) {
 const t=findTank(id),d=draftFor(t),r=recordFor(t),readOnly=Boolean(r?.confirmed);
 modal(`Animais de origem · ${t.name}`,`<p>Pré-seleção para novas aferições: finalidade Leite e DEL maior que zero em ${ptDate(state.date)}. As origens salvas não são recalculadas automaticamente.</p>
 <form id="origins-form" class="origin-list">${originPopulation.map(a=>{
   const e=originAt(a),reason=a.finalidade!=='LEITE'?'Finalidade Reprodução':e.del===null?'DEL não comprovado':`DEL ${e.del}`;
   return `<label class="origin-option"><input type="checkbox" name="animal" value="${a.id}" ${d.origins.includes(a.id)?'checked':''} ${readOnly||!e.eligible?'disabled':''}><span><strong>${esc(a.name)} · ${a.id}</strong><small>${esc(reason)} · ${a.finalidade==='LEITE'?'Finalidade Leite':'Fora da seleção leiteira'}</small></span>${badge(e.eligible?'Elegível':'Fora do critério',e.eligible?'ok':'pending')}</label>`;
 }).join('')}</form><p class="context-note">DEL 0 e finalidade diferente de Leite ficam fora da pré-seleção. Este critério está em revisão no mockup; não dispensa os controles sanitários.</p>`,readOnly?[{text:'Fechar',run:close}]:[{text:'Cancelar',run:close},{text:'Aplicar seleção',cls:'primary',run:()=>{
   const selected=[...$('#origins-form').querySelectorAll('input:checked')].map(input=>input.value);
   if(JSON.stringify([...selected].sort())!==JSON.stringify([...d.origins].sort())){d.origins=selected;d.dirty=true;d.error='';}
   finishDialog();render();
 }}],!readOnly);
}
function selectedTank() {
 const available=activeTanks(),context=`${state.date}:${state.session}`;
 const chosen=available.find(t=>t.id===state.selectedTanks[context])||available.find(t=>recordFor(t))||available[0];
 if(chosen)state.selectedTanks[context]=chosen.id;
 return chosen;
}
function tankPicker(selected) {
 return `<div class="tank-picker"><label for="capture-tank">Tanque desta aferição<select id="capture-tank">${activeTanks().map(t=>`<option value="${t.id}" ${selected.id===t.id?'selected':''}>${esc(t.name)} · ${liters(t.capacity)}${recordFor(t)?' · aferição salva':''}</option>`).join('')}</select></label><p>Registre somente os tanques utilizados. Para outro tanque na mesma ordenha, troque a seleção; os rascunhos e aferições são preservados.</p></div>`;
}
function manageTanks() {
 modal('Configuração dos tanques',`<div class="tank-catalog">${tanks.map(t=>MockupUI.ActionPanel({title:t.name,description:`${liters(t.capacity)} · versão ${t.version} · ${t.active?'Ativo':'Inativo'}`,body:`<p>${esc([t.manufacturer,t.model,t.serial&&`Série ${t.serial}`].filter(Boolean).join(' · ')||'Especificações adicionais não informadas')}</p><p class="context-note">${t.points.length} pontos de conversão cadastrados. Vigência: ${ptDate(t.since)}.</p>`,actions:MockupUI.Button('Nova versão do tanque',`data-config-tank="${t.id}"`,icon('settings'))})).join('')}</div>`,[{text:'Fechar',run:close},{text:'Cadastrar tanque',cls:'primary',run:()=>{finishDialog();tankDialog();}}]);
 $$('[data-config-tank]').forEach(button=>button.onclick=()=>{const id=button.dataset.configTank;finishDialog();tankDialog(id);});
}
function recoveryDialog() {
 modal('Estados da prévia',MockupUI.ActionPanel({title:'Catálogo de produtos',description:'Controles exclusivos da demonstração, separados da rotina de produção.',actions:MockupUI.Button('Simular falha','data-demo-state="error"',icon('info'))+MockupUI.Button('Simular lista vazia','data-demo-state="empty"',icon('box'))+MockupUI.Button('Restaurar produtos','data-demo-state="ready"',icon('check'))}),[{text:'Fechar',run:close}]);
 $$('[data-demo-state]').forEach(button=>button.onclick=()=>{state.products=button.dataset.demoState;state.mode='geral';finishDialog();goto('ordenhas');render();notify('Estado ilustrativo atualizado. O preenchimento foi preservado.');});
}
function draftFor(t){const k=key(t);if(!drafts.has(k)){const r=recordFor(t);drafts.set(k,{mm:r?.mm==null?'':String(r.mm),liters:r?String(r.liters):'',nature:r?.nature||'COMERCIAL',responsible:r?.responsible||'',origins:[...(r ? r.origins : automaticOrigins())],note:r?.note||'',dirty:false,error:''});}return drafts.get(k);}
function tankCard(t){const r=recordFor(t),shown=r?.tank||t,d=draftFor(t),k=key(t),ef=entryFields.get(k)||{product:'',reason:''};entryFields.set(k,ef);
 return `<article class="tank-form" data-tank="${t.id}"><header><span class="tank-icon">${icon('tank')}</span><div><h3>${esc(shown.name)} · ${liters(shown.capacity)}</h3><p>${r?.confirmed?'Confirmada no estoque':r?'Aferição salva · ainda não confirmada no estoque':'Aferição não registrada'}<small>Versão do tanque ${r?.tank.version||t.version}</small></p></div></header>${originsPanel(t,d,r)}${d.dirty?`<div class="draft-line" role="status">Rascunho nesta prévia <button class="outline" data-reset="${t.id}">Descartar rascunho</button></div>`:''}<fieldset ${r?.confirmed?'disabled':''}><div class="fields"><label>Régua (mm)<input inputmode="decimal" data-field="mm" value="${esc(d.mm)}" aria-label="Régua de ${esc(t.name)}" placeholder="Opcional"></label><label>Litros desta ordenha<input inputmode="decimal" data-field="liters" value="${esc(d.liters)}" aria-label="Litros de ${esc(t.name)}" placeholder="Não aferido"></label><label>Natureza<select data-field="nature" aria-label="Natureza de ${esc(t.name)}">${['COMERCIAL','NAO_COMERCIAL','COLOSTRO'].map(n=>`<option value="${n}" ${d.nature===n?'selected':''}>${natureName(n)}</option>`).join('')}</select></label><label>Responsável<input data-field="responsible" value="${esc(d.responsible)}" aria-label="Responsável por ${esc(t.name)}"></label></div><label class="block-field">Motivo da correção ou declaração da natureza<input data-field="note" value="${esc(d.note)}" aria-label="Motivo da aferição de ${esc(t.name)}" placeholder="Informe ao corrigir ou declarar a natureza"></label><div class="tank-actions"><button class="primary" data-save-tank="${t.id}">${icon('save')}Salvar aferição</button></div></fieldset>${d.error?errorText(d.error):''}${r&&!r.confirmed?`<div class="entry-area"><label class="block-field">Produto para o estoque<select data-product="${t.id}" ${state.products!=='ready'?'disabled':''} aria-label="Produto para ${esc(t.name)}"><option value="">Selecione</option><option value="leite" ${ef.product?'selected':''}>Leite a granel · L</option></select></label><label class="block-field">Motivo da confirmação<input data-entry-reason="${t.id}" value="${esc(ef.reason)}" aria-label="Motivo da confirmação de ${esc(t.name)}"></label>${state.products==='error'?`<div class="form-error" role="alert"><p>Não foi possível carregar os produtos para o estoque.</p><button class="outline" data-retry>Tentar novamente</button></div>`:state.products==='loading'?'<p role="status">Carregando produtos…</p>':state.products==='empty'?'<p role="status">Nenhum produto ativo em litros, sem rastreamento de partidas. Confira o cadastro de produtos.</p>':''}<button class="outline" data-confirm-tank="${t.id}" ${d.dirty||state.products!=='ready'||!ef.product||ef.reason.trim().length<5?'disabled':''}>Confirmar entrada no estoque</button><p class="context-note">Salvar a aferição registra produção. Confirmar gera uma entrada da mesma origem.</p></div>`:''}</article>`;}
function ordenhas() {
 const individual=state.mode==='individual', selected=selectedTank();
 return `<div class="mode-choice"><div class="subswitch" aria-label="Forma de aferição"><button data-mode="geral" aria-pressed="${!individual}">Produção geral</button><button data-mode="individual" aria-pressed="${individual}">Controle individual</button></div>${individual?MockupUI.Button('Ficha do animal · Produção','data-go="animal"',icon('cow')):''}</div>`+(individual?individualScreen():title('Ordenha em foco','Escolha o tanque e registre o volume desta ordenha.',dateControl())+sessionTabs()+`<div class="capture"><section><div class="section-head"><div><h3>Aferição · ${esc(names[state.session])}</h3><p>${measured(state.session)} ${measured(state.session)===1?'tanque com aferição salva':'tanques com aferição salva'}.</p></div><button class="outline" id="new-tank">${icon('plus')}Cadastrar tanque</button></div>${selected?tankPicker(selected)+tankCard(selected):'<div class="empty">Cadastre um tanque para registrar esta ordenha.</div>'}</section>${productionSummary()}</div><p class="context-note">A régua representa somente o leite desta ordenha. Cada tanque usa sua própria tabela; não há conversão automática por capacidade nem interpolação de pontos ausentes.</p>`);
}
function individualScreen(){return title('Controle individual','Medição nas datas aferidas. Não representa a produção dos dias entre os controles.',dateControl())+sessionTabs(true)+`<div class="capture"><section><div class="toolbar"><button class="outline" id="last-control">Ver último controle · 15/10/2026</button></div>${toolbar('Buscar por nome ou brinco')}<div class="table-wrap capture-table"><table><thead><tr><th>Animal</th><th>Litros nesta ordenha</th><th>Situação</th></tr></thead><tbody>${animals.filter(a=>(a.name+a.id).toLowerCase().includes(state.search.toLowerCase())&&(state.filter!=='pendentes'||a.values[state.session]===null)).map(a=>`<tr><td><div class="animal-cell"><span class="avatar-animal">${icon('cow')}</span><span><button class="outline" data-animal-sheet="${a.id}">${a.name}</button><small>Brinco ${a.id}</small></span></div></td><td><div class="liters"><input data-animal="${a.id}" inputmode="decimal" aria-label="Litros de ${a.name}, brinco ${a.id}" value="${a.values[state.session]===null?'':num(a.values[state.session])}" placeholder="—"><span>L</span></div></td><td>${badge(a.values[state.session]===null?'Pendente':'Registrado',a.values[state.session]===null?'pending':'ok')}</td></tr>`).join('')}</tbody></table></div>${foot(animals.length)}<p class="notice">${configAt(state.date).fonte==='GERAL'?'A fonte diária desta data é a aferição geral. Este controle individual não gera nova entrada no estoque.':'A fonte diária desta data é individual. A confirmação depende das medições e regras da sessão.'}</p></section><aside class="summary"><h3>Controle periódico</h3><p>A cada ${configAt(state.date).intervalo} ${configAt(state.date).unidade==='MESES'?'mês(es)':'dia(s)'}. Medições extras continuam permitidas.</p><p class="context-note">Para usar máquinas diariamente, configure 1 dia. Produção e qualidade individual ficam na ficha do animal.</p><button class="outline" data-go="animal">Abrir Produção de Aurora</button></aside></div>`;}
function saveTank(id){const t=findTank(id),d=draftFor(t),r=recordFor(t),mm=numberValue(d.mm),l=numberValue(d.liters);d.error='';if(state.date>'2026-10-23')d.error='A ordenha deve ter data até hoje (23/10/2026 nesta demonstração).';else if(l===null||!Number.isFinite(l)||l<0||l>(r?.tank.capacity||t.capacity))d.error='Informe litros entre zero e a capacidade do tanque.';else if(!d.responsible.trim())d.error='Informe o responsável pela aferição.';else if((r||d.nature!=='COMERCIAL')&&d.note.trim().length<5)d.error='Informe o motivo da correção ou da declaração da natureza.';else if(mm!==null){const point=(r?.tank||t).points.find(p=>p.mm===mm);if(!point)d.error='Esta leitura não consta na tabela. Complete a tabela ou informe somente litros, deixando a régua em branco.';else if(point.l!==l)d.error=`A tabela indica ${num(point.l)} L para ${num(mm)} mm.`;}
 if(d.error){render();return;}records.set(key(t),{date:state.date,session:state.session,tank:structuredClone(r?.tank||t),liters:l,mm,nature:d.nature,origins:[...d.origins],responsible:d.responsible,note:d.note,version:(r?.version||0)+1,confirmed:false});drafts.delete(key(t));render();notify('Aferição salva somente nesta prévia. Ainda não confirmada no estoque.');}
function confirmTank(id){const t=findTank(id),r=recordFor(t),d=draftFor(t),ef=entryFields.get(key(t));if(!r||d.dirty||state.products!=='ready'||!ef?.product||ef.reason.trim().length<5)return;r.confirmed=true;render();notify('Entrada simulada. Não foi criado movimento real de estoque.');}
function configDialog(){const c=configAt(state.date);modal('Configurações de produção',`<form id="config-form" class="fields"><p class="full">Defina a rotina do sítio. Datas já registradas conservam sua configuração.</p><label>Vigente desde<input name="since" type="date" required value="2026-10-24"></label><label>Fonte da produção diária<select name="source"><option value="GERAL">Aferição geral nos tanques</option><option value="INDIVIDUAL">Medições individuais completas</option></select></label><fieldset class="full"><legend>Controle individual dos animais</legend><div class="fields"><label>Aferir a cada<input name="interval" type="number" min="1" max="365" step="1" value="${c.intervalo}" required></label><label>Unidade do intervalo<select name="unit"><option value="MESES">Meses</option><option value="DIAS">Dias</option></select></label></div><p class="context-note">Mensal: 1 mês. Medição diária com máquinas: 1 dia. Medições extras continuam permitidas.</p></fieldset><label>Ordenhas por dia<input name="count" type="number" min="1" max="12" value="${c.nomes.length}" required></label><label>Nomes, separados por vírgula<input name="names" value="${esc(c.nomes.join(', '))}"></label><p class="full">A frequência das ordenhas é independente do intervalo individual. Somente a fonte diária escolhida compõe produção e estoque.</p><div id="modal-error" class="full"></div></form>`,[{text:'Cancelar',run:close},{text:'Salvar na prévia',cls:'primary',run:()=>{const f=$('#config-form');if(!f.reportValidity())return;const v=new FormData(f),count=Number(v.get('count')),since=v.get('since');if(byDay(since).length){$('#modal-error').innerHTML=errorText('Já há aferições nesta data. Escolha uma nova vigência para preservar o histórico.');return;}let ns=v.get('names').split(',').map(n=>n.trim()).filter(Boolean);ns=Array.from({length:count},(_,i)=>ns[i]||`Ordenha ${i+1}`);configs.push({desde:since,fonte:v.get('source'),intervalo:Number(v.get('interval')),unidade:v.get('unit'),nomes:ns});state.date=since;state.session=0;state.mode=v.get('source')==='GERAL'?'geral':'individual';finishDialog();render();notify('Nova vigência simulada. Os dias anteriores foram preservados.');}}],true);$('#config-form [name=source]').value=c.fonte;$('#config-form [name=unit]').value=c.unidade;}
function tankDialog(id){const t=tanks.find(x=>x.id===id);modal(t?'Nova versão do tanque':'Cadastrar tanque',`<form id="tank-form" class="fields"><p class="full">Especificações e tabela própria do tanque. Aferições anteriores conservam a versão utilizada.</p><label>Nome do tanque<input name="name" value="${esc(t?.name||'')}" required></label><label>Capacidade (L)<input name="capacity" type="number" min="1" value="${t?.capacity||''}" required></label><label>Vigente desde<input name="since" type="date" value="${state.date}" required></label><label>Fabricante<input name="manufacturer" value="${esc(t?.manufacturer||'')}"></label><label>Modelo<input name="model" value="${esc(t?.model||'')}"></label><label>Número de série ou ordem<input name="serial" value="${esc(t?.serial||'')}"></label><label class="check full"><input name="active" type="checkbox" ${t?.active===false?'':'checked'}>Disponível para novas aferições</label><h3 class="full">Conversão da régua</h3><label class="full">Referência da tabela<input name="reference" value="${esc(t?.reference||'')}"></label><label class="full">Tabela de conversão — milímetros;litros<textarea name="points" rows="6" placeholder="100;336,7">${t?t.points.map(p=>`${p.mm};${p.l}`).join('\n'):''}</textarea></label><p class="full">Um ponto por linha. Sem tabela, registre os litros aferidos diretamente. Pontos ausentes não serão estimados. Os pontos desta prévia são demonstrativos.</p><div class="full" id="modal-error"></div></form>`,[{text:'Cancelar',run:close},{text:t?'Salvar nova versão':'Salvar tanque',cls:'primary',run:()=>{const f=$('#tank-form');if(!f.reportValidity())return;const d=new FormData(f),points=[];let bad=false;for(const line of d.get('points').trim().split('\n').filter(Boolean)){const parts=line.split(';').map(numberValue);if(parts.length!==2||parts.some(v=>v===null||!Number.isFinite(v)||v<0)||parts[1]>Number(d.get('capacity'))||points.some(p=>p.mm===parts[0])){bad=true;break;}points.push({mm:parts[0],l:parts[1]});}if(bad){$('#modal-error').innerHTML=errorText('Confira a tabela: use milímetros;litros, pontos únicos e volumes dentro da capacidade.');return;}const data={id:t?.id||`t${Date.now()}`,name:d.get('name').trim(),capacity:Number(d.get('capacity')),since:d.get('since'),manufacturer:d.get('manufacturer'),model:d.get('model'),serial:d.get('serial'),active:d.has('active'),reference:d.get('reference'),points,version:(t?.version||0)+1};tankVersions.push(structuredClone(data));if(t)Object.assign(t,data);else tanks.push(data);finishDialog();render();notify('Configuração simulada. As aferições guardadas mantêm a versão anterior.');}}],true);}
function estoque(){const rs=[...records.values()].filter(r=>r.confirmed),sum=n=>rs.filter(r=>r.nature===n).reduce((s,r)=>s+r.liters,0);return title('Estoque de leite','Saldo com origem confirmada, separado por natureza.',`<button class="outline" data-go="ordenhas">Ver aferições</button>`)+figures([['Comercial disponível',liters(sum('COMERCIAL')),'Valor de produção a apurar'],['Não comercial',liters(sum('NAO_COMERCIAL')),'Sem venda · origem identificada'],['Colostro',sum('COLOSTRO')?liters(sum('COLOSTRO')):'Nenhuma origem','Fluxo próprio das crias']])+table(['Data e ordenha','Tanque / versão','Natureza','Litros disponíveis','Custo','Ação'],rs.map(r=>[`${ptDate(r.date)} · ${configAt(r.date).nomes[r.session]}`,`${esc(r.tank.name)}<small>Versão ${r.tank.version}</small>`,badge(natureName(r.nature)),liters(r.liters),badge('A apurar','pending'),`<button class="outline" data-void-key="${esc(key(r.tank,r.session,r.date))}">Regularizar entrada</button>`]))+`<div class="toolbar after-section"><button class="outline" id="feed">Destinar para alimentação</button><button class="outline" id="discard">Registrar descarte</button></div><p class="context-note">O custo pendente não impede o registro do volume e sua destinação. Comercial, não comercial e colostro mantêm suas origens.</p>`;}
function coletas(){const rows=collectionRows.filter(r=>r.join(' ').toLowerCase().includes(state.search.toLowerCase())&&state.filter!=='pendentes');return title('Coletas de leite','A retirada mantém data, volume e comprador, mesmo sem preço final.',`<button class="primary" id="new-collection">${icon('plus')}Registrar retirada</button>`)+figures([['Volume retirado','955 L','18 a 21/out · quatro retiradas ilustrativas'],['Comprador',trade.buyer,trade.reference],['Preço final',trade.closed?money(trade.price):'A definir',trade.closed?'Negociado no fechamento':'Operação aberta']])+toolbar('Buscar comprador ou período')+table(['Data e hora','Comprador','Volume físico','Operação','Situação'],rows)+foot(rows.length)+`<p class="context-note">Uma coleta pode reunir origens de vários dias. Esses litros não são a produção do dia da retirada.</p>`;}
function sampleDates(a){return `<dl class="date-facts"><div><dt>Data da amostra</dt><dd>${ptDate(a.date)}</dd></div><div><dt>Resultado laboratorial</dt><dd>${ptDate(a.resultDate)}</dd></div><div><dt>Recebimento do laudo</dt><dd>${ptDate(a.received)}</dd></div><div><dt>Cadastro no sistema</dt><dd>${esc(a.registered)}</dd></div></dl>`;}
function sampleResults(a){return Object.keys(a.results).length?`<dl class="quality-values">${sampleFields.filter(([code])=>a.results[code]!=null).map(([code,name,unit])=>`<div><dt>${name}</dt><dd>${num(a.results[code])} ${unit}</dd></div>`).join('')}</dl>`:'<p>Aguardando resultado. Ausência não representa zero.</p>';}
function qualidade(){const rows=samples.filter(a=>state.qualitySubject==='TODAS'||a.subject===state.qualitySubject);return title('Qualidade do leite','Análises individuais e coletivas, independentes da venda.',`<button class="primary" id="quality-new">${icon('plus')}Registrar amostra</button>`)+`<div class="subswitch quality-switch"><button data-quality="TODAS" aria-pressed="${state.qualitySubject==='TODAS'}">Todas</button><button data-quality="COLETIVO" aria-pressed="${state.qualitySubject==='COLETIVO'}">Coletivas</button><button data-quality="ANIMAL" aria-pressed="${state.qualitySubject==='ANIMAL'}">Por animal</button></div>`+table(['Amostra / origem','Coleta','Resultado','Recebimento','Situação','Ação'],rows.map(a=>[`${a.id}<small>${esc(a.origin)}</small>`,ptDate(a.date),ptDate(a.resultDate),ptDate(a.received),badge(Object.keys(a.results).length?'Resultado registrado':'Aguardando laudo',Object.keys(a.results).length?'ok':'pending'),`<button class="outline" data-sample="${a.id}">Ver análise · v${a.version}</button>`]))+`<div class="notice"><p>O formato demonstrativo usa gordura (%) e CCS (mil células/mL). Campos e unidades vêm do laudo configurado; não são limites sanitários nem fórmula de preço.</p></div>`;}
function sampleDetail(id){const a=samples.find(x=>x.id===id);modal(`${a.id} · ${a.origin}`,sampleDates(a)+sampleResults(a)+`<p class="context-note">Formato: Controle leiteiro · exemplo. Versão da amostra ${a.version}. Os resultados de uma amostra coletiva não são atribuídos aos animais.</p>${MockupUI.ActionPanel({title:`Histórico de correções · ${a.history.length}`,body:a.history.map(h=>`<p>Versão ${h.version} → ${h.version+1} · ${esc(h.reason)}<small>Resultado: ${ptDate(h.resultDate)} · Recebimento: ${ptDate(h.received)}</small></p>`).join('')||'<p>Sem correções nesta prévia.</p>'})}`,[{text:'Fechar',run:close},{text:'Corrigir datas',cls:'primary',run:()=>{finishDialog();editSampleDates(id);}}]);}
